```rust
let res = {
    let mut stream = me.store.resolve(self.key);
    try_ready!(me.actions.recv.poll_pushed(&mut stream)
};

Ok(Async::Ready(res.map(|(h, key)| {
    me.store.resolve(key).ref_inc();

    let opaque_ref = OpaqueStreamRef {
        inner: self.inner.clone(),
        key: key,
    };

    (h, opaque_ref)
}))
```

